// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock reports the current time. It is an injection point for tests.
type Clock interface {
	Now() time.Time
}

type systemClock struct{}

func (systemClock) Now() time.Time { return time.Now() }

// SystemClock is the default Clock backed by the wall clock.
var SystemClock Clock = systemClock{}

// Limiter is a concurrency-safe token-bucket rate limiter.
// The zero value is not usable; construct with NewLimiter.
type Limiter struct {
	mu       sync.Mutex
	rate     float64       // tokens per second
	burst    float64       // bucket capacity
	tokens   float64       // available tokens
	last     time.Time     // last refill time
	clock    Clock
}

// NewLimiter creates a Limiter refilling at rate tokens per second with the
// given burst capacity. rate must be > 0, burst must be >= 1, and clock must
// be non-nil (pass nil to use SystemClock).
func NewLimiter(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 || math.IsNaN(rate) || math.IsInf(rate, 0) {
		return nil, errors.New("ratelimit: rate must be a positive, finite number")
	}
	if burst < 1 {
		return nil, errors.New("ratelimit: burst must be at least 1")
	}
	if clock == nil {
		clock = SystemClock
	}
	now := clock.Now()
	return &Limiter{
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst), // start full
		last:   now,
		clock:  clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
// It never blocks; if fewer than n tokens are available it returns false
// and leaves the bucket unchanged.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = math.Min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
	need := float64(n)
	if l.tokens < need {
		return false
	}
	l.tokens -= need
	return true
}

// Tokens returns the number of tokens currently available (approximate if
// other goroutines are concurrently consuming tokens).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	elapsed := l.clock.Now().Sub(l.last).Seconds()
	if elapsed > 0 {
		return math.Min(l.burst, l.tokens+elapsed*l.rate)
	}
	return l.tokens
}
