package ratelimit

import (
	"sync"
	"testing"
	"time"
)

// fakeClock is a manually advanced Clock for deterministic tests.
type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func newFakeClock(start time.Time) *fakeClock { return &fakeClock{now: start} }

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(d)
}

func TestNewLimiterValidation(t *testing.T) {
	tests := []struct {
		name    string
		rate    float64
		burst   int
		clock   Clock
		wantErr bool
	}{
		{"valid", 1, 1, nil, false},
		{"nil clock ok", 2.5, 10, nil, false},
		{"zero rate", 0, 10, nil, true},
		{"negative rate", -1, 10, nil, true},
		{"NaN rate", nan(), 10, nil, true},
		{"Inf rate", inf(), 10, nil, true},
		{"zero burst", 1, 0, nil, true},
		{"negative burst", 1, -3, nil, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			l, err := NewLimiter(tc.rate, tc.burst, tc.clock)
			if (err != nil) != tc.wantErr {
				t.Fatalf("NewLimiter(%v, %d) err = %v, wantErr %v", tc.rate, tc.burst, err, tc.wantErr)
			}
			if err == nil && l == nil {
				t.Fatal("NewLimiter returned nil limiter with nil error")
			}
		})
	}
}

func nan() float64 { f := 0.0; return f / f }
func inf() float64 { f := 0.0; return 1 / f }

func TestAllowN(t *testing.T) {
	start := time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)

	tests := []struct {
		name       string
		rate       float64
		burst      int
		actions    []action
		wantResult []bool
	}{
		{
			name:  "burst exhausted then denied",
			rate:  1, burst: 3,
			actions:    []action{{n: 1}, {n: 1}, {n: 1}, {n: 1}},
			wantResult: []bool{true, true, true, false},
		},
		{
			name:  "multi-token request within burst",
			rate:  1, burst: 5,
			actions:    []action{{n: 3}, {n: 2}, {n: 1}},
			wantResult: []bool{true, true, false},
		},
		{
			name:  "refill over time",
			rate:  2, burst: 2, // 1 token per 500ms
			actions:    []action{{n: 2}, {advance: 500 * time.Millisecond}, {n: 1}, {n: 1}},
			wantResult: []bool{true, true, false},
		},
		{
			name:  "refill capped at burst",
			rate:  1, burst: 2,
			actions:    []action{{n: 2}, {advance: 10 * time.Second}, {n: 2}, {n: 1}},
			wantResult: []bool{true, true, false},
		},
		{
			name:  "zero-token request always allowed",
			rate:  1, burst: 1,
			actions:    []action{{n: 1}, {n: 0}, {n: 0}},
			wantResult: []bool{true, true, true},
		},
		{
			name:  "negative request denied",
			rate:  1, burst: 1,
			actions:    []action{{n: -1}, {n: 1}},
			wantResult: []bool{false, true},
		},
		{
			name:  "partial refill insufficient",
			rate:  1, burst: 1,
			actions:    []action{{n: 1}, {advance: 500 * time.Millisecond}, {n: 1}},
			wantResult: []bool{true, false},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			clk := newFakeClock(start)
			l, err := NewLimiter(tc.rate, tc.burst, clk)
			if err != nil {
				t.Fatalf("NewLimiter: %v", err)
			}
			for i, a := range tc.actions {
				if a.advance > 0 {
					clk.Advance(a.advance)
					continue
				}
				if got := l.AllowN(a.n); got != tc.wantResult[i] {
					t.Fatalf("action %d: AllowN(%d) = %v, want %v", i, a.n, got, tc.wantResult[i])
				}
			}
		})
	}
}

type action struct {
	n       int
	advance time.Duration
}

func TestAllow(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	l, err := NewLimiter(1, 1, clk)
	if err != nil {
		t.Fatal(err)
	}
	if !l.Allow() {
		t.Fatal("first Allow() = false, want true")
	}
	if l.Allow() {
		t.Fatal("second Allow() = true, want false")
	}
	clk.Advance(time.Second)
	if !l.Allow() {
		t.Fatal("Allow() after refill = false, want true")
	}
}

func TestTokens(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	l, err := NewLimiter(2, 3, clk)
	if err != nil {
		t.Fatal(err)
	}
	l.AllowN(2)
	if got := l.Tokens(); got != 1 {
		t.Fatalf("Tokens() = %v, want 1", got)
	}
	clk.Advance(time.Second)
	if got := l.Tokens(); got != 3 {
		t.Fatalf("Tokens() after refill = %v, want 3 (capped at burst)", got)
	}
}

func TestConcurrentAllow(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	l, err := NewLimiter(1000, 100, clk)
	if err != nil {
		t.Fatal(err)
	}
	const goroutines = 50
	var wg sync.WaitGroup
	var allowed int64
	var mu sync.Mutex
	for i := 0; i < goroutines; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 10; j++ {
				if l.Allow() {
					mu.Lock()
					allowed++
					mu.Unlock()
				}
			}
		}()
	}
	wg.Wait()
	if allowed > 100 {
		t.Fatalf("allowed %d tokens, want <= burst 100", allowed)
	}
}
